import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { caretRight, check } from "../../../icons/index";
import { addConstructedStyle } from "../../utils/browser";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
let id = 0;

/**
 * @since 2.0
 * @status experimental
 *
 * @slot - The menu item's label.
 * @slot prefix - Used to prepend an icon or similar element to the menu item.
 * @slot suffix - Used to append an icon or similar element to the menu item.
 *
 * @part base - The component's base wrapper.
 * @part checked-icon - The container that wraps the checked icon.
 * @part prefix - The prefix container.
 * @part label - The menu item label.
 * @part suffix - The suffix container.
 */

@Component({
	tag: "hbr-menu-item",
	styleUrl: "menu-item.scss",
	shadow: true,
})
export class MenuItem {
	sheet: CSSStyleSheet = new CSSStyleSheet();
	menuItem: HTMLElement;
	menuLabel: HTMLElement;
	componentId = `hbr-menu-item-${++id}`;
	positioner: HTMLElement;
	nestedFixer: HTMLElement;
	_gap: HTMLElement;
	private toid: null | ReturnType<typeof setTimeout> = null;

	@Element() host: HTMLHbrMenuItemElement;

	@State() hasFocus = false;

	@State() isTextWrapped = false;

	private syncGhostText = (e: Event) => {
		const menu = this.host.closest("hbr-menu");
		this.isTextWrapped = !!(menu && menu.hasAttribute("text-wrap"));
		const ghost = this.host.shadowRoot?.querySelector("span[data-ghost]");
		if (this.isTextWrapped) {
			const slot = e.currentTarget as HTMLSlotElement;
			const text = slot
			 .assignedNodes({ flatten: true })
			 .map((n) => n.textContent ?? "")
			 .join("")
			 .trim();
			if (ghost) {
				ghost.textContent = text;
			}
		} else {
			if (ghost) {
				ghost.textContent = "";
			}
		}
	};

	/** Set to true to draw the item in a checked state. */
	@Prop({ reflect: true, mutable: true }) checked = false;

	/** Set to true to draw the item in an indeterminate state. */
	@Prop({ reflect: true }) indeterminate = false;

	/** A unique value to store in the menu item. This can be used as a way to identify menu items when selected. */
	@Prop({ reflect: true }) value = "";

	/** Set to true to draw the menu item in a disabled state. */
	@Prop({ reflect: true }) disabled = false;

	/** Set this to true in case of category items. */
	@Prop({ reflect: true }) indented = false;

	/** Set aria-controls to the component. */
	@Prop() ariacontrols = undefined;

	/** Set this to true in case of using inside another hbr-menu. */
	@Prop({ reflect: true }) nested = false;

	/** Set to enable checkbox type menu item. */
	@Prop({ reflect: true }) checkbox = false;

	/** Set to true to indicate if the menu item is focused. */
	@Prop({ reflect: true, mutable: true }) open = false;

	/** Set to show checkmark on the right side of the menu item. */
	@Prop({ reflect: true, mutable: true }) checkMark = false;

	/** Set to true to disable the selected state style - menu-item--checked. */
	@Prop({ reflect: true, mutable: true }) noSelectedState = false;

	/** The hierarchical level of the menu item in a multi-level menu */
	@Prop({ reflect: true }) level = 1;

	/** Set tab index prop. */
	@Prop({ reflect: true }) tabindx: string;

	/** This is set for left side navigation */
	@Prop({ reflect: true }) nav = false;

	/** The sentiment of the menu item. */
	@Prop({ mutable: true, reflect: true }) sentiment = "neutral";

	/** The size of the menu item. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Set this to true when menu item is checked in a nested menu. */
	@Prop({ reflect: true, mutable: true }) nestedSelected = false;

	/** Set this to true in case of non-interactive element in the menuitem. */
	@Prop({ reflect: true }) noninteractive = false;

	/** Set this to true in case of using inside the hbr-cascader. */
	@Prop({ reflect: true }) cascading = false;

	/** show right caret if has children. */
	@Prop({ reflect: true }) hasChildren = false;

	/** Set this to true in case of loading items. */
	@Prop({ reflect: true }) loading = false;

	/** enable focus on interactive element in the menuitem. */
	@Prop({ reflect: true }) nestedInteractive = false;

	/** Toggle css classes: The density of the menu item. */
	@Prop({ reflect: true }) density: "comfy" | "compact" = "compact";

	@Event({ eventName: "hbr-checked" }) hbrChecked: EventEmitter<{
		item: HTMLHbrMenuItemElement;
	}>;

	@Event({ eventName: "hbr-hide-popover" }) hbrHidePopover: EventEmitter;

	@Event({ eventName: "hbr-trigger-focus" }) hbrTriggerFocus: EventEmitter;

	connectedCallback() {
		this.handleCheckboxState = this.handleCheckboxState.bind(this);
		this.handleNestedState = this.handleNestedState.bind(this);
		this.handleHostClick = this.handleHostClick.bind(this);
		this.handleLoading = this.handleLoading.bind(this);
		if (!this.checkbox) {
			this.host.setAttribute("role", "menuitem");
		} else {
			this.handleTypeChange();
		}
		this.host.addEventListener("click", this.handleHostClick);
	}

	private handleHostClick(event: MouseEvent) {
		// Prevent the click event from being emitted when the button is disabled or loading
		if (this.disabled) {
			event.preventDefault();
			event.stopImmediatePropagation();
		}
	}

	/** Sets focus on the button. */
	@Method()
	async setFocus(options?: FocusOptions, hasDelay?: boolean, delay?: number) {
		this.hasFocus = true;
		if (hasDelay) {
			this.toid && clearTimeout(this.toid);
			this.toid = setTimeout(() => {
				this.toid && clearTimeout(this.toid);
				this.menuItem?.focus(options);
			}, delay || 0);
		} else {
			this.menuItem?.focus(options);
		}
	}

	/** Removes focus from the button. */
	@Method()
	async removeFocus() {
		this.hasFocus = false;
		this.menuItem.blur();
	}

	componentDidLoad() {
		this.handleCheckboxState();
	}

	handleCheckboxState() {
		if (this.checkbox) {
			const checkbox = this.host.querySelector("hbr-checkbox");
			if (checkbox) {
				checkbox.checked = this.checked;
				checkbox.disabled = this.disabled;
				checkbox.indeterminate = this.indeterminate;
			}
		}
	}

	@Watch("disabled")
	@Watch("indeterminate")
	handleDisabledState() {
		this.handleCheckboxState();
	}

	@Watch("checked")
	handleEmitSelectEvent() {
		this.checked && this.hbrChecked.emit();
		this.handleCheckboxState();
		this.handleNestedState();
		// Only checkbox types can receive the aria-checked attribute
		if (this.checkbox) {
			this.host.setAttribute("aria-checked", this.checked ? "true" : "false");
		} else {
			this.host.removeAttribute("aria-checked");
		}
	}

	@Watch("checkbox")
	handleTypeChange() {
		if (this.checkbox) {
			this.host.setAttribute("role", "menuitemcheckbox");
			this.host.setAttribute("aria-checked", this.checked ? "true" : "false");
		}
	}

	closestElement = (selector, el) => {
		return (
			(el && el !== document && el !== window && el.closest(selector)) ||
			(el && this.closestElement(selector, el.getRootNode().host))
		);
	};

	handleNestedState() {
		if (this.nested && this.checked) {
			this.nestedSelected = false;
		}
	}

	handleCheckboxClick = (e) => {
		if (this.cascading) {
			return;
		}
		if (this.handleNestedInteractiveClose(e)) return;
		if (this.checkbox && !this.disabled) {
			this.checked = !this.checked;
		}
	};

	handleCheckboxKeyDown = (e) => {
		if (["Enter", " "].includes(e.key) && this.checkbox && !this.disabled) {
			this.checked = !this.checked;
		}
	};

	conditionalWrapper = ({ condition, children }) => {
		return condition ? (
			<div class="menu-item__wrapper" part="wrapper">
				{children}
			</div>
		) : (
			children
		);
	};

	syncGapHeigh = () => {
		if (this._gap) {
			const height = this.menuItem?.getBoundingClientRect().height;
			if (height) {
				this._gap.style.height = `${height}px`;
			}
		}
	};

	@Watch("loading")
	handleLoading(value) {
		if (value) {
			this.host.setAttribute("aria-busy", "true");
		} else {
			this.host.removeAttribute("aria-busy");
		}
	}

	@Watch("open")
	syncNestedMenuTop() {
		if (this.nested) {
			const top = this.positioner?.getBoundingClientRect().top;
			if (this.nestedFixer && typeof top === "number") {
				this.nestedFixer.style.top = `${top}px`;
			}
		}
	}

	handleOnMouseEnter = () => {
		if (this.cascading) return;
		if (this.nested) {
			this.open = true;
			this.syncGapHeigh();
		}
	};

	handleOnMouseLeave = () => {
		if (this.cascading) {
			return;
		}
		if (this.nested) {
			this.open = false;
		}
	};

	handleNestedMenuOpen = (e) => {
		if (this.nested && !this.disabled && ["Enter", " "].includes(e.key)) {
			e.stopPropagation();
			this.open = !this.open;
		}
		if (this.nested && !this.disabled && ["ArrowRight"].includes(e.key)) {
			e.stopPropagation();
			this.open = true;
			// have to manually get the element and focus due to the async setFocus method will cause a delay
			this.menuItem?.classList.add("menu-item--open");
			const item = this.host?.querySelector(
				"hbr-menu hbr-menu-item:not(disabled)",
			) as HTMLHbrMenuItemElement;
			if (item) {
				const base = item.shadowRoot.querySelector(
					"[part='base']",
				) as HTMLElement;
				base?.focus();
			}
		}
	};

	// handle interactive element close popover
	// TODO: support `floated`
	handleNestedInteractiveClose = (e) => {
		let noninteractive = false;
		const timeout = e.type === "click" ? 0 : 140;
		if (
			(this.noninteractive && [" ", "Enter"].includes(e.key)) ||
			(this.noninteractive && e.type === "click")
		) {
			const ele = e.target;
			if (ele instanceof HTMLElement) {
				// @ts-ignore
				if (
					ele.hasAttribute("data-close") ||
					// @ts-ignore
					typeof ele?.setFocus === "function"
				) {
					setTimeout(() => {
						this.hbrHidePopover.emit();
						this.hbrTriggerFocus.emit();
					}, timeout);
					noninteractive = true;
				}
			}
			e.stopPropagation();
		}
		return noninteractive;
	};
	handleOnKeyDown = (e) => {
		if (this.cascading) {
			return;
		}
		if (this.handleNestedInteractiveClose(e)) return;
		this.handleCheckboxKeyDown(e);
		this.handleNestedMenuOpen(e);
	};

	render() {
		const isInShellNav = !!this.host.closest("hbr-shell-nav");

		const { sentiment } = this;
		const showCheckMark =
			!this.nav &&
			!this.nested &&
			this.checkMark &&
			this.checked &&
			!this.noninteractive &&
			!this.hasChildren;
		const showRightCaret = isInShellNav && this.hasChildren;

		this.sheet.replaceSync(`
		:host {
			--level: ${this.level === 1 ? "-4px" : "-90%"};
		`);
		if (this.host) addConstructedStyle(this.host.shadowRoot, this.sheet);

		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<Host aria-controls={this.ariacontrols}>
				<div
					aria-disabled={this.disabled ? "true" : "false"}
					aria-haspopup={this.nested ? "true" : null}
					aria-expanded={this.nested ? (this.open ? "true" : "false") : null}
					ref={(el) => {
						this.menuItem = el;
					}}
					part="base"
					class={{
						"menu-item": true,
						"menu-item--checked":
							this.noninteractive || this.noSelectedState
								? false
								: this.checked,
						"menu-item--disabled": this.disabled,
						"menu-item--focused": this.hasFocus,
						"menu-item--nested": this.nested,
						"menu-item--indented": this.indented,
						"menu-item--nested-selected": this.nestedSelected,
						"menu-item--checkbox": this.checkbox,
						"menu-item--nav": this.nav,
						"menu-item--shell-nav": isInShellNav,
						[`menu-item--${sentiment}`]: true,
						"menu-item--small": this.size === "small",
						"menu-item--medium": this.size === "medium",
						"menu-item--large": this.size === "large",
						"menu-item--comfy": isInShellNav && this.density === "comfy",
						"menu-item--compact": isInShellNav && this.density === "compact",
						"menu-item--open": this.open,
						"menu-item--noninteractive": this.noninteractive,
					}}
					tabindex={
						this.disabled
							? "-1"
							: this.tabindx
							  ? this.tabindx
							  : this.hasFocus
								  ? "0"
								  : "-1"
					}
					// aria-labelledby={this.componentId}
					onKeyDown={this.handleOnKeyDown}
					onClick={this.handleCheckboxClick}
					onMouseEnter={this.handleOnMouseEnter}
					onMouseLeave={this.handleOnMouseLeave}
				>
					{this.conditionalWrapper({
						condition: this.sentiment === "admin",
						children: (
							<Fragment>
								<span part="checked-icon" class="menu-item__check" />

								<span part="prefix" class="menu-item__prefix">
									<slot name="prefix" />
								</span>

								<span
									ref={(el) => {
										this.menuLabel = el;
									}}
									part="label"
									class={{
										"menu-item__label": true,
										"menu-item__text-wrap": this.isTextWrapped
									}}
									id={this.componentId}
								>
									<span data-ghost class={{"menu-item__ghost": this.isTextWrapped}} aria-hidden="true" />
									<slot onSlotchange={this.syncGhostText} />
								</span>

								<span part="suffix" class="menu-item__suffix">
									<slot name="suffix" />
									{showCheckMark && (
										<span part="check-mark" class="menu-item__check-mark">
											<hbr-icon asset={customSystemIcons?.check || check} />
										</span>
									)}
									{showRightCaret && (
										<span part="check-mark" class="menu-item__right-caret">
											<hbr-icon
												asset={customSystemIcons?.["caret-right"] || caretRight}
											/>
										</span>
									)}
								</span>

								{this.nav && this.checked && !this.noninteractive && (
									<div part="icon-checked" class="icon-checked">
										<hbr-icon asset={customSystemIcons?.check || check} />
									</div>
								)}

								{this.nested && (
									<div
										part="trigger-gap"
										class={{
											"dropdown__trigger-gap": true,
											"dropdown__trigger-gap-open": this.open,
											"dropdown__trigger-gap-right": this.open,
										}}
									>
										<div
											part="trigger-gap-fixed"
											ref={(el) => {
												this._gap = el;
											}}
											class={{
												"dropdown__trigger-gap__fixed": this.open,
											}}
										/>
									</div>
								)}

								{this.nested && (
									<span
										class="menu-item__positioner"
										ref={(el) => {
											this.positioner = el;
										}}
									>
										<span
											part="nested"
											class="menu-item__nested"
											ref={(el) => {
												this.nestedFixer = el;
											}}
										>
											<slot name="nested" />
										</span>
									</span>
								)}
							</Fragment>
						),
					})}
				</div>
			</Host>
		);
	}
}
