import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	h,
} from "@stencil/core";
import { getTextContent } from "../../utils/slot";

/**
 * @since 0.0.11
 * @status stable
 *
 * @slot - The menu's content, including menu items, menu dividers, and menu labels.
 *
 * @part base - The component's base wrapper.
 *
 *
 */

@Component({
	tag: "hbr-menu",
	styleUrl: "menu.scss",
	shadow: true,
})
export class Menu {
	typeToSelectString = "";
	typeToSelectTimeout: NodeJS.Timeout;

	@Element() host: HTMLHbrMenuElement;

	/** Defines the menu's visual style. */
	@Prop({ reflect: true }) variant: "context" | null;

	/** Set this to true in case of using inside another hbr-menu. */
	@Prop({ mutable: true, reflect: true }) nested = false;

	/** Set this to true when you are use menu on navigation */
	@Prop() nav = false;

	/** Deprecated, Set this to true if this is the last menu in a hbr-shell-nav. This is to set padding bottom to 0. */
	@Prop() last = false;

	/** Set this to true in case of using inside the hbr-cascader. */
	@Prop({ reflect: true }) cascading = false;

	/** Set this to true to enable text wrapping for menu items. */
	@Prop({ reflect: true}) textWrap = false;

	/** Emitted when a menu item is selected. */
	@Event({ eventName: "hbr-select" }) hbrSelect: EventEmitter<{
		item: HTMLHbrMenuItemElement;
		event?: MouseEvent;
	}>;

	connectedCallback() {
		this.handleClick = this.handleClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.getItems = this.getItems.bind(this);
		this.host.setAttribute("role", "menu");
	}

	/**
	 * Initiates type-to-select logic, which automatically selects an option based on what the user is currently typing.
	 * The key passed will be appended to the internal query and the selection will be updated. After a brief period, the
	 * internal query is cleared automatically. This method is intended to be used with the keydown event. Useful for
	 * enabling type-to-select when the menu doesn't have focus.
	 */
	@Method()
	async typeToSelect(key: string) {
		clearTimeout(this.typeToSelectTimeout);
		this.typeToSelectTimeout = setTimeout(() => {
			this.typeToSelectString = "";
		}, 750);
		this.typeToSelectString += key.toLowerCase();
		const items = this.getItems();
		for (const item of items) {
			const slot = item.shadowRoot.querySelector(
				"slot:not([name])",
			) as HTMLSlotElement;
			const label = getTextContent(slot).toLowerCase().trim();
			if (
				label.substring(0, this.typeToSelectString.length) ===
				this.typeToSelectString
			) {
				item.setFocus();
				break;
			}
		}
	}

	@Method()
	async getMenuItems() {
		return this.getItems() || [];
	}

	private handleSlotChange() {
		const items = this.getItems();

		// Reset the roving tab index when the slotted items change
		if (items.length > 0) {
			if (!this.cascading) {
				items[0]?.setFocus();
			}
		}
	}

	getCurrentLevelItems = () => {
		const items = Array.from(
			this.host.querySelectorAll("hbr-menu-item"),
		) as Array<HTMLHbrMenuItemElement>;
		return items.filter((item) => {
			const menu = item?.closest("hbr-menu");
			return this.host === menu;
		});
	};

	getItems() {
		let items = Array.from(
			this.nested
				? this.host.querySelectorAll("hbr-menu-item")
				: this.getCurrentLevelItems(),
		) as Array<HTMLHbrMenuItemElement>;
		items = items.reduce((acc, cur) => {
			if (cur.nestedInteractive) {
				const eleList = Array.from(cur.querySelectorAll("*"));
				eleList.forEach((ele: HTMLElement) => {
					if (ele instanceof HTMLElement) {
						// @ts-ignore
						if (
							ele &&
							// @ts-ignore
							!ele.disabled &&
							// @ts-ignore
							ele?.setFocus &&
							// @ts-ignore
							typeof ele?.setFocus === "function"
						) {
							acc.push(ele);
						}
						if (ele.getAttribute("tabindex") === "0") {
							acc.push(ele);
						}
					}
				});
			} else {
				if (!cur.disabled && !cur.noninteractive) acc.push(cur);
			}
			return acc;
		}, []);
		return items.filter((item) => {
			const menu = item?.closest("hbr-menu");
			if (this.host === menu) {
				return true;
			}
			return !menu?.nested;
		});
	}

	getActiveItem() {
		const isMenuItem = document.activeElement.closest("hbr-menu-item");
		return this.getItems().find((i) => i === isMenuItem);
	}

	handleClick(event: MouseEvent) {
		const target = event.target as HTMLElement;
		const item = target.closest("hbr-menu-item");

		if (item?.noninteractive) return;
		if (item && !item.disabled && !item.nested) {
			this.hbrSelect.emit({ item, event });
		}
	}

	triggerTheFocus = (element) => {
		if (typeof element?.setFocus === "function") {
			const base = element?.shadowRoot.querySelector(
				"[part='base']",
			) as HTMLElement;
			base?.focus();
		} else if (typeof element?.focus === "function") {
			element.focus();
		}
	};

	handleKeyDown(event: KeyboardEvent) {
		// Make a selection when pressing enter
		if (["Enter", " "].includes(event.key)) {
			const item = this.getActiveItem();
			if (item?.noninteractive) return;
			event.preventDefault();

			if (item) {
				// event.stopImmediatePropagation();

				/** event is being used on hbr-select multi */
				// Simulate a click to support @click handlers on menu items that also work with the keyboard
				item.click();
			} else {
				const focused = this.getItems()?.findIndex((item) =>
					item.shadowRoot?.querySelector("[tabindex='0']"),
				);
				if (focused > -1) {
					this.getItems()[focused].click();
				}
			}
		} else if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
			if (this.nested) {
				event.stopPropagation();
			}
			const items = this.getItems();
			const selectedItem = this.getActiveItem();
			const datePicker = document.activeElement.closest("hbr-date-picker");
			let index = -1;
			if (selectedItem) {
				index = items.indexOf(selectedItem);
			} else if (datePicker) {
				const focused = this.getItems()?.findIndex((item) =>
					item.shadowRoot?.querySelector("[tabindex='0']"),
				);
				if (focused > -1) {
					index = focused;
				}
			} else {
				index = items.indexOf(selectedItem);
			}

			const _index = index;
			if (items.length > 0) {
				event.preventDefault();

				if (event.key === "ArrowDown") {
					index++;
				} else if (event.key === "ArrowUp") {
					index--;
				} else if (event.key === "Home") {
					index = 0;
				} else if (event.key === "End") {
					index = items.length - 1;
				}

				if (index < 0) {
					index = items.length - 1;
				}
				if (index > items.length - 1) {
					index = 0;
				}

				if (datePicker) {
					const currentItem = this.getItems()[_index] as HTMLHbrMenuItemElement;
					if (currentItem) {
						currentItem.tabindx = "-1";
					}

					items[index].tabindx = "0";
				}

				this.triggerTheFocus(items[index]);

				return;
			}
		} else if (["ArrowLeft", "Escape"].includes(event.key)) {
			if (this.nested) {
				event.stopPropagation();
				const item = this.host.closest("hbr-menu-item");
				if (item) {
					item.open = false;
					item.setFocus();
				}
			}
			return;
		} else if ("ArrowRight" === event.key) {
			return;
		} else {
			this.typeToSelect(event.key);
		}
	}

	render() {
		const navParent = this.host.closest("hbr-shell-nav");
		const isInShellNav = !!navParent;

		return (
			<Host>
				<div
					part={`${this.nested ? "base nested" : "base"}`}
					class={{
						menu: true,
						[`menu--${this.variant}`]: true,
						"menu--nested": this.nested,
						"menu--nav": this.nav,
						"menu--shell-nav": isInShellNav,
						"menu--shell-nav--last": this.last,
						"menu--cascading": this.cascading,
					}}
					onClick={this.handleClick}
					onKeyDown={this.handleKeyDown}
				>
					<slot onSlotchange={this.handleSlotChange} />
				</div>
			</Host>
		);
	}
}
