import {
  Component,
  Element,
  Event,
  type EventEmitter,
  Host,
  Listen,
  Method,
  Prop,
  State,
  Watch,
  h,
} from "@stencil/core";
import { parseDuration } from "../../utils/animate";
import { generateShortID } from "../../utils/function-helper";
import { scrollIntoView } from "../../utils/scroll";
import { getNearestTabbableElement } from "../../utils/browser";

/**
 * @since 0.0.13
 * @status stable
 *
 * @description Dropdowns expose additional content that "drops down" in a panel.
 *
 * @slot trigger - The dropdown's trigger.
 * @slot - The dropdown's content.
 *
 * @part base - The component's base wrapper.
 * @part trigger - The container that wraps the trigger.
 * @part panel - The panel that gets shown when the dropdown is open.
 */

@Component({
  tag: "hbr-dropdown",
  styleUrl: "dropdown.scss",
  shadow: true,
})
export class Dropdown {
  private hoverTimeout: number;
  private resizeObserver: ResizeObserver;
  //for highlighting first item when dropdown is on display
  private isKeyboardEvent = false;
  private isFirstItemFocus = true;
  private shortId = generateShortID();
  private skipHandlingFocusOnTrigger: boolean;

  private popupRef: HTMLHbrPopupElement;
  private anchorRef: HTMLElement;
  private popupContentRef: HTMLElement;
  private isFirstTimeOpen = true;

  @State() isSelected = false;

  @Element() host: HTMLHbrDropdownElement;

  /**
   * The element the dropdown will be anchored to. If the anchor is external, you can provide a reference to an element or CSS selector via this prop. If the anchor lives inside the popover, donot pass this prop
   */
  @Prop() anchor: HTMLElement | string;

  /**
   * The flip boundary describes clipping element(s) that overflow will be checked relative to when flipping. By
   * default, the boundary includes overflow ancestors that will cause the element to be clipped. If needed, you can
   * change the boundary by passing a reference to one or more elements to this property.
   */
  @Prop() flipBoundary: HTMLElement;

  /** The amount of padding, in pixels, to exceed before the flip behavior will occur. */
  @Prop() flipPadding = 0;

  /** User assigned or self generated dropdown Id for reference */
  @Prop({ reflect: true }) contentId = `hbr-dropdown-id-${this.shortId}`;

  /** Indicates whether or not the dropdown is open. You can use this in lieu of the show/hide methods. */
  @Prop({ mutable: true, reflect: true }) open = false;

  /**
   * The preferred placement of the dropdown panel. Note that the actual placement may vary as needed to keep the panel
   * inside of the viewport.
   */
  @Prop({ reflect: true }) placement:
    | "top"
    | "top-start"
    | "top-end"
    | "bottom"
    | "bottom-start"
    | "bottom-end"
    | "right"
    | "right-start"
    | "right-end"
    | "left"
    | "left-start"
    | "left-end" = "bottom-start";

  /** Disables the dropdown so the panel will not open. */
  @Prop({ reflect: true }) disabled = false;

  /** Determines whether the dropdown should hide when a menu item is selected. */
  @Prop({ reflect: true }) closeOnSelect = true;

  /** The dropdown will close when the user interacts outside of this element (e.g. clicking). */
  @Prop({ mutable: true }) containingElement: HTMLElement;

  /** The dropdown menu fits the width of the trigger if the menu is too small */
  @Prop({ mutable: true, reflect: true }) menuFitTrigger = false;

  @Prop({ mutable: true, reflect: true }) panelFitTrigger = false;

  @Prop({ mutable: true, reflect: true }) manualTrigger = false;

  /** Enables multi select. With this enabled, value will be an array. */
  @Prop({ reflect: true }) multiple = false;

  @Prop({ reflect: true }) noFocusoutTillPanelClose = false;

  /** The distance in pixels from which to offset the panel away from its trigger. */
  @Prop() distance = 4;

  /** The distance in pixels from which to offset the panel along its trigger. */
  @Prop() skidding = 0;

  /** When set, this will cause the popup to automatically resize itself to prevent it from overflowing. */
  @Prop({ reflect: true }) autoSize: "horizontal" | "vertical" | "both" | "off";

  /** The amount of padding, in pixels, to exceed before the auto-size behavior will occur. */
  @Prop({ reflect: true }) autoSizePadding;

  /**
   * Enable this option to prevent the panel from being clipped when the component is placed inside a container with `overflow: auto|scroll`
   */
  @Prop() hoist: boolean | string = false;

  /** trigger by click or hover */
  @Prop({ reflect: true }) trigger: "hover" | "click" = "click";

  /** Dropdown size */
  @Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

  /** Shows an arrow next to the label */
  @Prop({ reflect: true }) menu = false;

  /** Sentiment for dropdown. */
  @Prop({ reflect: true }) sentiment: "interact" | string = "interact";

  // $$custom
  @Prop({ mutable: true, reflect: true }) value: string | Array<any>;

  /** Used for cascading menus. */
  @Prop({ mutable: true, reflect: true }) nested = false;

  /** Set to true to control the dropdown's state from the application / framework's side */
  @Prop({ mutable: true, reflect: true }) uncontrolled = false;

  /** close the menu when scroll */
  @Prop({ reflect: true }) closeOnScroll = false;

  /** Enable the native popover feature so that it layers above all other elements, it needs hoist true, since 2.15.0 */
  @Prop() enablePopover = false;

  /** Emitted when the dropdown opens. Calling `event.preventDefault()` will prevent it from being opened. */
  @Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

  /** Emitted after the dropdown opens and all transitions are complete. */
  @Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

  /** Emitted when the dropdown closes. Calling `event.preventDefault()` will prevent it from being closed. */
  @Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

  /** Emitted after the dropdown closes and all transitions are complete. */
  @Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

  /** Emitted when a menu item is selected */
  @Event({ eventName: "hbr-select" }) hbrSelect: EventEmitter<{
    item: HTMLHbrMenuItemElement;
    event?: KeyboardEvent;
  }>;

  // $$custom
  /** Emitted when body is clicked. Calling `event.preventDefault()` will prevent the popover from closing. */
  @Event({ eventName: "hbr-dismiss" }) hbrDismiss: EventEmitter;

  /** Shows the dropdown panel. */
  @Method()
  async show() {
    if (this.open) {
      return undefined;
    }
    this.open = true;
  }

  /** Hides the dropdown panel */
  @Method()
  async hide() {
    if (!this.open) {
      return undefined;
    }
    this.open = false;
  }

  /** Forces the dropdown's menu to reposition. */
  @Method()
  async reposition() {
    if (!this.open) {
      return;
    }
    this.popupRef?.reposition();
  }

  // $$custom
  @Listen("hbr-hide-popover")
  listenClosePopover() {
    this.hide();
  }

  // $$custom
  @Listen("hbr-trigger-focus")
  listenTriggerFocus() {
    this.focusOnTrigger();
  }

  // $$custom
  @Watch("anchor")
  handleAnchorChange() {
    if (this.anchor && typeof this.anchor === "string") {
      this.anchorRef = document?.querySelector(this.anchor);
    } else if (this.anchor instanceof HTMLElement) {
      this.anchorRef = this.anchor;
    }
    if (this.anchorRef) {
      this.bindEventsToAnchor();
    }
  }

  // $$custom
  @Watch("value")
  setMenuValue() {
    if (this.uncontrolled) return;
    if (this.multiple) {
      this.syncItemsFromValue();
    } else {
      this.handleItemSelected();
    }
    this.isSelected = this.multiple ? !!this.value?.length : !!this.value;
  }

  @Watch("open")
  async handleOpenChange() {
    if (!this.popupRef) return;
    if (this.getIsComboBox()) {
      const anchorRef = this.anchorRef as HTMLHbrComboboxElement;
      if (anchorRef.disabled) return;
      anchorRef.open = this.open;
    }
    if (this.disabled) {
      this.open = false;
      return;
    }

    this.updateAccessibleTrigger();

    if (this.open) {
      // Show
      this.hbrShow.emit();
      this.addOpenListeners();
      this.popupContentRef.hidden = false;
      this.popupRef.active = true;
      this.hbrAfterShow.emit();
      await this.focusOnFirstMenuItem();
    } else {
      // Hide
      this.hbrHide.emit();
      this.removeOpenListeners();
      this.popupRef.active = false;
      this.popupContentRef.hidden = true;
      this.hbrAfterHide.emit();
      const items = Array.from(
        this.host.querySelectorAll("hbr-menu-item[open]")
      ) as Array<HTMLHbrMenuItemElement>;
      items.forEach((item) => {
        item.open = false;
      });
    }
  }

  addOpenListeners() {
    this.popupContentRef.addEventListener("hbr-select", this.handlePanelSelect);
    this.popupContentRef.addEventListener("keydown", this.handleKeyDown);
    document.addEventListener("keydown", this.handleDocumentKeyDown);
    document.addEventListener("mousedown", this.handleDocumentMouseDown);
    this.closeOnScroll &&
      document.addEventListener("scroll", this.handleCloseOnScroll, true);
  }

  removeOpenListeners() {
    if (this.popupContentRef) {
      this.popupContentRef.removeEventListener(
        "hbr-select",
        this.handlePanelSelect
      );
      this.popupContentRef.removeEventListener("keydown", this.handleKeyDown);
    }
    document.removeEventListener("keydown", this.handleDocumentKeyDown);
    document.removeEventListener("mousedown", this.handleDocumentMouseDown);
    this.closeOnScroll &&
      document.removeEventListener("scroll", this.handleCloseOnScroll, true);
  }

  connectedCallback() {
    if (!this.containingElement) {
      this.containingElement = this.host;
    }

    // $$custom , are all these bindings needed?
    this.handleDocumentKeyDown = this.handleDocumentKeyDown.bind(this);
    this.handleDocumentMouseDown = this.handleDocumentMouseDown.bind(this);
    this.handleMenuItemActivate = this.handleMenuItemActivate.bind(this);
    this.handlePanelSelect = this.handlePanelSelect.bind(this);
    this.handleTriggerClick = this.handleTriggerClick.bind(this);
    this.handleTriggerKeyDown = this.handleTriggerKeyDown.bind(this);
    this.handleTriggerKeyUp = this.handleTriggerKeyUp.bind(this);
    this.handleTriggerSlotChange = this.handleTriggerSlotChange.bind(this);
    this.handleItemSelected = this.handleItemSelected.bind(this);
    this.setNestedSelected = this.setNestedSelected.bind(this);
    this.syncItemsFromValue = this.syncItemsFromValue.bind(this);
    this.syncValueFromItems = this.syncValueFromItems.bind(this);
    this.getValueAsArray = this.getValueAsArray.bind(this);
    this.handleMenuSelect = this.handleMenuSelect.bind(this);
    this.handleOpenChange = this.handleOpenChange.bind(this);
    this.updateAccessibleTrigger = this.updateAccessibleTrigger.bind(this);
    this.reposition = this.reposition.bind(this);
    this.show = this.show.bind(this);
    this.hide = this.hide.bind(this);
    this.handleCloseOnScroll = this.handleCloseOnScroll.bind(this);
    this.resizeObserver = new ResizeObserver(() => this.resizeMenu());
  }

  componentDidLoad() {
    this.handleAnchorChange();
    this.popupContentRef.hidden = !this.open;

    // If the dropdown is visible on init, update its position
    if (this.open) {
      this.addOpenListeners();
      this.popupRef.active = true;
    }

    // $$custom
    if (!this.getIsComboBox()) {
      this.setMenuValue();
    }
    (this.menuFitTrigger || this.panelFitTrigger) &&
      this.resizeObserver.observe(this.host);
    // this.bindEventsToAnchor();
  }

  disconnectedCallback() {
    this.resizeObserver?.unobserve(this.host);
    this.removeOpenListeners();
    this.hide();
  }

  handleCloseOnScroll() {
    if (this.open) this.open = false;
  }

  // $$custom - // slightly modified and has extra cases
  focusOnTrigger() {
    let trigger;
    if (this.anchor) {
      trigger = this.anchorRef;
    } else {
      const slot = this.anchorRef.querySelector(
        "slot[name='trigger']"
      ) as HTMLSlotElement;
      trigger = slot?.assignedElements({ flatten: true })[0] as any;
    }
    if (trigger) {
      if (typeof trigger.setFocus === "function") {
        trigger.setFocus();
        this.skipHandlingFocusOnTrigger = true;
      } else if (typeof trigger.focus === "function") {
        trigger.focus();
        this.skipHandlingFocusOnTrigger = true;
      }
    }
  }

  getMenu() {
    const menu = this.host.querySelector("hbr-menu") as HTMLHbrMenuElement;
    return menu ? menu : null;
  }

  // $$custom
  resizeMenu() {
    if (this.menuFitTrigger) {
      const menu = this.getSlotMenu();
      if (menu.length) {
        menu[0].style.setProperty(
          "--min-width",
          `${this.anchorRef.clientWidth}px`
        );
        // Above doesn't work because width overrides min-width, so set one of the child item's min-width as well
        const firstChild = menu[0].firstElementChild as HTMLElement;
        firstChild?.style.setProperty(
          "min-width",
          `${this.anchorRef.clientWidth}px`
        );
      }
      this.reposition();
    }
    if (this.panelFitTrigger) {
      this.popupContentRef.style.minWidth = `${this.anchorRef.clientWidth}px`;
      this.reposition();
    }
  }

  private handleKeyDown = (event: KeyboardEvent) => {
    // Close when escape is pressed inside an open dropdown. We need to listen on the panel itself and stop propagation
    // in case any ancestors are also listening for this key.
    if (this.open && event.key === "Escape") {
      event.stopPropagation();
      this.hide();
      this.focusOnTrigger();
    }
  };

  handleDocumentKeyDown(event: KeyboardEvent) {
    this.isKeyboardEvent = true;
    // Close when escape or tab is pressed
    if (event.key === "Escape" && this.open) {
      event.stopPropagation();
      this.focusOnTrigger();
      this.hide();
      return;
    }

    // Handle tabbing
    if (event.key === "Tab") {
      // Tabbing within an open menu should close the dropdown and refocus the trigger
      if (
        this.open &&
        document.activeElement?.tagName.toLowerCase() === "hbr-menu-item"
      ) {
        event.preventDefault();
        this.hide();
        this.focusOnTrigger();
        return;
      }

      // Tabbing outside of the containing element closes the panel
      //
      // If the dropdown is used within a shadow DOM, we need to obtain the activeElement within that shadowRoot,
      // otherwise `document.activeElement` will only return the name of the parent shadow DOM element.
      setTimeout(() => {
        const activeElement =
          this.containingElement.getRootNode() instanceof ShadowRoot
            ? document.activeElement.shadowRoot?.activeElement
            : document.activeElement;

        if (
          !this.containingElement ||
          activeElement?.closest(
            this.containingElement.tagName.toLowerCase()
          ) !== this.containingElement
        ) {
          this.hide();
        }
      });
    }
  }

  getIsComboBox = () =>
    this.anchorRef && this.anchorRef?.tagName === "HBR-COMBOBOX";

  handleDocumentMouseDown(event: MouseEvent) {
    const path = event.composedPath() as Array<EventTarget>;
    if (
      this.containingElement &&
      !path.includes(this.host) &&
      !path.includes(this.anchorRef)
    ) {
      this.hide();
    }
  }

  handlePanelSelect(event: CustomEvent) {
    const target = event.target as HTMLElement;

    // Hide the dropdown when a menu item is selected
    if (this.closeOnSelect && target.tagName.toLowerCase() === "hbr-menu") {
      this.hide();
      this.focusOnTrigger();
    }
  }

  // $$custom
  handleMenuItemActivate(event: CustomEvent) {
    const item = event.target as HTMLHbrMenuItemElement;
    scrollIntoView(item, this.popupContentRef);
  }

  handleTriggerClick(_e, isKeyboardEvent?: boolean) {
    if (this.disabled || this.manualTrigger) return;
    if (this.open) {
      if (this.getIsComboBox()) return;
      this.hide();
    } else {
      this.show();
      this.isKeyboardEvent = !!isKeyboardEvent;
    }
  }

  handleTreeItemArrowUpDown = (key) => {
    if (
      this.anchorRef?.closest('[slot="interactive"]') &&
      this.anchorRef?.closest("hbr-tree-item")
    ) {
      if (["ArrowDown", "ArrowUp"].includes(key)) {
        return true;
      }
    }
  };

  handleTriggerKeyDown(event: KeyboardEvent) {
    if (this.manualTrigger) return;
    // When spacebar/enter is pressed, show the panel but don't focus on the menu. This let's the user press the same
    // key again to hide the menu in case they don't want to make a selection.
    const enterSpace = ["Enter", " "];
    if (this.getIsComboBox()) enterSpace.pop();
    if (enterSpace.includes(event.key)) {
      event.preventDefault();
      this.isKeyboardEvent = true;
      this.isFirstItemFocus = true;
      this.show();
    } else if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      if (this.handleTreeItemArrowUpDown(event.key)) return;
      event.preventDefault();
      if (event.key === "ArrowDown" || event.key === "Home") {
        this.isKeyboardEvent = true;
        this.isFirstItemFocus = true;
        this.open && this.focusOnFirstMenuItem();
        this.show();
        return;
      }
      if (event.key === "ArrowUp") {
        this.isKeyboardEvent = true;
        this.isFirstItemFocus = false;
        this.open && this.focusOnFirstMenuItem();
        this.show();
        return;
      }
    } else if (event.key === "Escape") {
      this.hide();
      this.focusOnTrigger();
      return;
    }
  }

  handleTriggerKeyUp(event: KeyboardEvent) {
    if (this.getIsComboBox()) return;
    // Prevent space from triggering a click event in Firefox
    this.isKeyboardEvent = true;
    if (event.key === " ") {
      event.preventDefault();
    }
  }

  handleTriggerSlotChange() {
    this.updateAccessibleTrigger();
  }

  //
  // Slotted triggers can be arbitrary content, but we need to link them to the dropdown panel with `aria-haspopup` and
  // `aria-expanded`. These must be applied to the "accessible trigger" (the tabbable portion of the trigger element
  // that gets slotted in) so screen readers will understand them. The accessible trigger could be the slotted element,
  // a child of the slotted element, or an element in the slotted element's shadow root.
  //
  // For example, the accessible trigger of an <hbr-button> is a <button> located inside its shadow root.
  //
  // To determine this, we assume the first tabbable element in the trigger slot is the "accessible trigger."
  //
  updateAccessibleTrigger() {
    let accessibleTrigger = null;
    if (this.anchor && this.anchorRef) {
      accessibleTrigger = getNearestTabbableElement(this.anchorRef);
    }
    if (!this.anchor && this.anchorRef) {
      const slot = this.anchorRef.querySelector("slot") as HTMLSlotElement;
      const assignedElements = slot.assignedElements({
        flatten: true,
      }) as HTMLElement[];
      accessibleTrigger = assignedElements.map(getNearestTabbableElement)[0];
    }
    if (accessibleTrigger) {
      accessibleTrigger.setAttribute("aria-haspopup", "true");
      accessibleTrigger.setAttribute(
        "aria-expanded",
        this.open ? "true" : "false"
      );
    }
  }

  // $$custom
  async focusOnFirstMenuItem() {
    if (this.menu && this.isKeyboardEvent) {
      this.isFirstTimeOpen && (await customElements.whenDefined("hbr-menu"));
      const menu = this.getMenu() as any;
      if (menu) {
        this.isFirstTimeOpen &&
          (await customElements.whenDefined("hbr-menu-item"));
        const menuItems = await menu.getMenuItems();
        if (menuItems.length) {
          let item: HTMLHbrMenuItemElement;
          if (this.isFirstItemFocus) {
            item = menuItems[0];
          } else {
            item = menuItems[menuItems.length - 1];
          }
          item?.setFocus({}, true, 100);
          if (this.isFirstTimeOpen) {
            this.isFirstTimeOpen = false;
          }
        }
      }
    }
    this.isKeyboardEvent = false;
  }

  // $$custom
  private handleFocus = () => {
    if (this.hasTrigger("focus") && !this.skipHandlingFocusOnTrigger) {
      this.show();
    }
    this.skipHandlingFocusOnTrigger = false;
  };

  // $$custom
  private hasTrigger(triggerType: string) {
    const triggers = this.trigger.split(" ");
    return triggers.includes(triggerType);
  }

  // $$custom
  private handleTriggerMouseEnter = () => {
    this.isKeyboardEvent = false;
    if (!this.disabled && this.hasTrigger("hover") && !this.manualTrigger) {
      const delay = parseDuration(
        getComputedStyle(this.host).getPropertyValue("--hide-delay")
      );
      clearTimeout(this.hoverTimeout);
      this.hoverTimeout = window.setTimeout(() => this.show(), delay);
    }
  };

  // $$custom
  handleTriggerMouseLeave = (e) => {
    if (!this.disabled && this.hasTrigger("hover") && !this.manualTrigger) {
      // if the event is on the trigger,
      // if pointer is within (this.distance) from around the panel, do not hide
      // OR if the event is on the panel,
      // if pointer is within (this.distance) from around the trigger, do not hide
      const rect = this.popupContentRef.getBoundingClientRect();
      if (
        e.clientX < rect.left - this.distance ||
        e.clientX > rect.right + this.distance ||
        e.clientY < rect.top - this.distance ||
        e.clientY > rect.bottom + this.distance
      ) {
        this.hide();
      }
    }
  };

  handlePopupContentMouseLeave = (_) => {
    if (
      this.open &&
      !this.disabled &&
      this.trigger === "hover" &&
      !this.manualTrigger
    ) {
      this.hide();
    }
  };

  // $$custom
  setNestedSelected(item) {
    const menuItem = item.closest("hbr-menu-item[nested]");
    if (menuItem?.nested) {
      menuItem.nestedSelected = true;
      const menu = menuItem.closest("hbr-menu");
      if (menu) {
        const parentItem = menu.closest("hbr-menu-item[nested]");
        parentItem && this.setNestedSelected(parentItem);
      }
    }
  }

  // $$custom
  handleItemSelected() {
    this.getItems().forEach((item: HTMLHbrMenuItemElement) => {
      const checked = item.value === this.value;
      if (item.nested && !checked) {
        item.nestedSelected = false;
      }
      checked && this.setNestedSelected(item);
      item.checked = checked;
    });
  }

  // $$custom
  getItems() {
    return [
      ...this.host.querySelectorAll<HTMLHbrMenuItemElement>("hbr-menu-item"),
    ];
  }

  // $$custom
  getValueAsArray() {
    if (this.multiple && this.value === "") {
      return [];
    }
    return Array.isArray(this.value) ? this.value : [this.value];
  }

  // $$custom
  syncItemsFromValue() {
    const menusItemList = this.getItems();
    const value = this.getValueAsArray();

    menusItemList.forEach((item) => {
      item.checked = value.includes(item.value);
    });
  }

  // $$custom
  syncValueFromItems() {
    const menusItemList = this.getItems();
    const checkedItems = menusItemList.filter((item) => item.checked);
    const checkedValues = checkedItems.map((item) => item.value);
    this.value = checkedValues;
  }

  // $$custom
  getSlotMenu() {
    const slot = this.popupContentRef.querySelector("slot") as HTMLSlotElement;
    return [...slot.assignedElements()].filter(
      (e) => e.tagName.toLocaleLowerCase() === "hbr-menu"
    ) as [HTMLHbrMenuElement];
  }

  // $$custom
  handleMenuSelect(e: CustomEvent) {
    if (this.uncontrolled) return;
    e.stopPropagation();
    if (e.detail?.item) {
      if (this.multiple) {
        this.syncValueFromItems();
      } else {
        this.getItems().forEach((item) => {
          if (e.detail?.item) item.checked = item === e.detail.item;
        });
      }
    }
    this.hbrSelect.emit(e.detail);
  }

  // $$custom
  handleMenuItemCheck = () => {
    if (this.uncontrolled) return;
    if (!this.multiple) {
      const menu = this.getMenu();
      const menuItems = menu
        ? Array.from(menu.querySelectorAll("hbr-menu-item"))
        : [];
      if (menuItems.length) {
        const checkedList: HTMLHbrMenuItemElement[] | [] = menuItems.filter(
          (item: HTMLHbrMenuItemElement) => item.checked
        );
        if (checkedList.length) this.value = checkedList[0].value;
      }
    }
  };

  private bindEventsToAnchor() {
    if (!this.anchorRef) return;
    //$$custom
    this.anchorRef.addEventListener("focus", this.handleFocus, true);

    this.anchorRef.onclick = this.handleTriggerClick;
    this.anchorRef.onkeydown = this.handleTriggerKeyDown;
    this.anchorRef.onkeyup = this.handleTriggerKeyUp;

    //$$custom
    this.anchorRef.onmouseenter = this.handleTriggerMouseEnter;
    this.anchorRef.onmouseleave = this.handleTriggerMouseLeave;
  }

  render() {
    const autoSize =
      this.autoSize === "off" ? undefined : this.autoSize || "vertical";
    const defaultPadding = this.autoSize === undefined ? 10 : 24;
    const autoSizePadding =
      this.autoSizePadding !== undefined
        ? this.autoSizePadding
        : defaultPadding;
    return (
      <Host>
        <hbr-popup
          part="base"
          exportparts="popup"
          id={this.contentId}
          placement={this.placement}
          distance={this.distance}
          skidding={this.skidding}
          strategy={this.hoist || this.hoist === "true" ? "fixed" : "absolute"}
          flip
          shift
          autoSize={autoSize}
          enablePopover={this.enablePopover}
          autoSizePadding={autoSizePadding}
          flipPadding={this.flipPadding}
          flipBoundary={this.flipBoundary}
          ref={(el) => {
            this.popupRef = el;
          }}
          anchor={this.anchor}
          class={{
            dropdown: true,
            "dropdown--open": this.open,
            "dropdown--menu": this.menu,
            "dropdown--selected": this.isSelected,
            "dropdown--disabled": this.disabled,
            "dropdown--small": this.size === "small",
            "dropdown--medium": this.size === "medium",
            "dropdown--large": this.size === "large",
          }}
          onhbr-select={this.handleMenuSelect}
          onhbr-checked={this.handleMenuItemCheck}
          onFocusout={(e) => {
            if (this.noFocusoutTillPanelClose && this.open) {
              e.stopPropagation();
            }
          }}
        >
          {!this.anchor ? (
            <span
              part="trigger"
              slot="anchor"
              class="dropdown__trigger"
              ref={(el) => {
                this.anchorRef = el;
              }}
            >
              <slot
                name="trigger"
                onSlotchange={this.handleTriggerSlotChange}
              />
            </span>
          ) : null}

          <div
            ref={(el) => {
              this.popupContentRef = el;
            }}
            part="panel"
            class={{
              dropdown__panel: true,
              "dropdown__panel-autosize":
                this.autoSize && this.autoSize !== "off",
            }}
            aria-hidden={this.open ? "false" : "true"}
            aria-labelledby={this.contentId}
            onMouseLeave={this.handlePopupContentMouseLeave}
          >
            <slot />
          </div>
        </hbr-popup>
      </Host>
    );
  }
}
